    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🔧","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A unguwarmu ana gina makaranta. Ana buƙatar bulo da yawa.","en":"Our neighbourhood is building a school. Many blocks are needed."}},{"text":{"ha":"Za ka iya koyon yadda ake yin bulo da interlock?","en":"Can you learn how blocks and interlock are made?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Yashi, siminti da ruwa su ne kayan farawa. Abubuwa na asali ne.","en":"Sand, cement and water are the starting materials. They are resources."}},{"text":{"ha":"Idan an haɗa su aka matse a ƙira, sai a samu bulo: sabon abu mai amfani.","en":"When mixed and pressed in a mould they become a block: a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Siminti yana ƙona fata da idanu. Manya ne kawai ke taɓa shi, da safar hannu, takalmi mai ƙarfi da abin rufe hanci.","en":"Cement can burn skin and eyes. Only adults handle it, with gloves, strong boots and a dust mask."}},{"text":{"ha":"Bulo yana da nauyi, injin matsewa kuma yana iya matse yatsa. Yara su tsaya a nesa. Wannan wasa ne kawai.","en":"Blocks are heavy and the press can crush fingers. Children stay back. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🏖️","title":{"ha":"Yashi","en":"Sand"},"lines":[{"k":"whatIs","text":{"ha":"Ƙananan hatsin dutse.","en":"Tiny grains of rock."}},{"k":"whatDoes","text":{"ha":"Yana cika bulo ya ba shi ƙarfi.","en":"It fills the block and gives it strength."}},{"k":"whyNeeded","text":{"ha":"Ba tare da yashi ba, bulo zai tsage.","en":"Without sand a block would crack."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🪣","title":{"ha":"Siminti","en":"Cement"},"lines":[{"k":"whatIs","text":{"ha":"Gari mai launin toka da ke manne abubuwa.","en":"A grey powder that glues things together."}},{"k":"whatDoes","text":{"ha":"Idan ya haɗu da ruwa, yana taurare.","en":"When it meets water it hardens."}},{"k":"whyNeeded","text":{"ha":"Shi ne yake ba bulo ƙarfi.","en":"It is what makes the block strong."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"💧","title":{"ha":"Ruwa","en":"Water"},"lines":[{"k":"whatIs","text":{"ha":"Ruwa mai tsabta.","en":"Clean water."}},{"k":"whatDoes","text":{"ha":"Yana sa siminti ya fara taurare.","en":"It starts the cement hardening."}},{"k":"whyNeeded","text":{"ha":"Ruwa kaɗan ko da yawa duka suna lalata bulo, don haka sai a bi mai gini.","en":"Too little or too much spoils a block, so follow the trained mason."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🧩","title":{"ha":"Ƙira da injin matsewa","en":"Mould and press"},"lines":[{"k":"whatIs","text":{"ha":"Akwati mai siffar bulo, ko injin da ke matse haɗin.","en":"A box shaped like a block, or a machine that presses the mix."}},{"k":"whatDoes","text":{"ha":"Yana ba haɗin siffa da ƙarfi.","en":"It gives the mix its shape and strength."}},{"k":"whyNeeded","text":{"ha":"Interlock yana da sassa da ke shiga juna, don haka ana gini da ƙarfi ba tare da siminti da yawa ba.","en":"Interlock blocks slot together, so walls are strong with less mortar."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🌤️","title":{"ha":"Warkewa (curing)","en":"Curing"},"lines":[{"k":"whatIs","text":{"ha":"A bar bulo a inuwa a riƙa fesa masa ruwa kwanaki.","en":"Keep blocks in the shade and sprinkle with water for days."}},{"k":"whatDoes","text":{"ha":"Yana barin siminti ya taurare sosai.","en":"It lets the cement harden fully."}},{"k":"whyNeeded","text":{"ha":"Idan bulo ya bushe da sauri, zai tsage.","en":"If a block dries too fast it will crack."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Ana sayar da bulo kowanne guda. Gini yana buƙatar su da yawa.","en":"Blocks are sold one by one. A building needs many."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bmeasure', 0, $j${"emoji":"⚖️","name":{"ha":"Auna kayan","en":"Measure the materials"},"text":{"ha":"Mai gini yana auna yashi, siminti da ruwa daidai.","en":"The mason measures the sand, cement and water exactly."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bdry', 1, $j${"emoji":"🥄","name":{"ha":"Haɗa busasshe","en":"Mix dry"},"text":{"ha":"Ana haɗa yashi da siminti busasshe har launi ya zama ɗaya.","en":"Sand and cement are mixed dry until the colour is even."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bwater', 2, $j${"emoji":"💧","name":{"ha":"Saka ruwa","en":"Add water"},"text":{"ha":"Ana saka ruwa kaɗan-kaɗan ana juyawa.","en":"Water is added a little at a time while mixing."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bfill', 3, $j${"emoji":"🧱","name":{"ha":"Cika ƙira","en":"Fill the mould"},"text":{"ha":"Ana cika ƙirar bulo da haɗin.","en":"The block mould is filled with the mix."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bpress', 4, $j${"emoji":"🔨","name":{"ha":"Matse haɗin","en":"Compact the mix"},"text":{"ha":"Ana matse haɗin a cikin ƙira don ya yi ƙarfi.","en":"The mix is compacted in the mould so it is strong."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bout', 5, $j${"emoji":"📤","name":{"ha":"Cire bulo a hankali","en":"Take the block out gently"},"text":{"ha":"Ana cire bulo a hankali kada ya karye.","en":"The block is taken out gently so it does not break."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'iprep', 6, $j${"emoji":"⛏️","name":{"ha":"Shirya ƙasa da siminti","en":"Prepare soil and cement"},"text":{"ha":"Ana tace ƙasa mai kyau a haɗa da ɗan siminti. Mai gini ne ke yanke adadi.","en":"Good soil is sieved and mixed with a little cement. The mason decides the amounts."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'imix', 7, $j${"emoji":"🥣","name":{"ha":"Haɗa da ruwa","en":"Mix with water"},"text":{"ha":"Ana haɗawa da ruwa kaɗan har ya yi ɗanshi daidai.","en":"It is mixed with a little water until the dampness is right."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ipress', 8, $j${"emoji":"⚙️","name":{"ha":"Matse a injin","en":"Press in the machine"},"text":{"ha":"Injin yana matse haɗin ya zama bulo mai siffar interlock.","en":"The press squeezes the mix into an interlocking block."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ifit', 9, $j${"emoji":"🧩","name":{"ha":"Kalli yadda suke shiga juna","en":"See how they fit together"},"text":{"ha":"Sassan interlock suna shiga juna kamar wasan haɗa hotuna.","en":"Interlock parts slot together like a puzzle."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cshade', 10, $j${"emoji":"🌤️","name":{"ha":"Ajiye a inuwa","en":"Keep in the shade"},"text":{"ha":"Ana ajiye bulo a inuwa, ba rana kai tsaye ba.","en":"Blocks are kept in the shade, not in direct sun."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cspray', 11, $j${"emoji":"💦","name":{"ha":"Fesa ruwa","en":"Sprinkle water"},"text":{"ha":"Ana fesa ruwa kaɗan sau biyu a rana na kwanaki.","en":"Sprinkle a little water twice a day for several days."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cwait', 12, $j${"emoji":"📅","name":{"ha":"Jira kwanaki","en":"Wait several days"},"text":{"ha":"Ana jira kwanaki kafin a yi amfani da bulo.","en":"Wait several days before using the blocks."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cstack', 13, $j${"emoji":"📚","name":{"ha":"Jera a hankali","en":"Stack carefully"},"text":{"ha":"Manya suna jera bulo a hankali kada ya faɗo.","en":"Adults stack the blocks carefully so none fall."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'sandcrete', 0, $j${"id":"sandcrete","emoji":"🧱","name":{"ha":"Bulon siminti","en":"Cement block"},"steps":["bmeasure","bdry","bwater","bfill","bpress","bout"],"summary":{"ha":"Bulon siminti: auna, haɗa busasshe, ruwa, ƙira, matsewa.","en":"Cement block: measure, dry mix, water, mould, compact."},"result":{"emoji":"🧱","name":{"ha":"Bulon siminti","en":"Cement block"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'interlock', 1, $j${"id":"interlock","emoji":"🧩","name":{"ha":"Bulon interlock","en":"Interlock block"},"steps":["iprep","imix","ipress","ifit"],"summary":{"ha":"Interlock: ƙasa da ɗan siminti, ana matsewa a injin, sassa suna shiga juna.","en":"Interlock: soil with a little cement, pressed in a machine, parts slot together."},"result":{"emoji":"🧩","name":{"ha":"Bulon interlock","en":"Interlock block"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'cure', 2, $j${"id":"cure","emoji":"🌤️","name":{"ha":"Warkewa da jerawa","en":"Curing and stacking"},"steps":["cshade","cspray","cwait","cstack"],"summary":{"ha":"Warkewa: inuwa, ruwa kaɗan, jira.","en":"Curing: shade, a little water, patience."},"result":{"emoji":"🏗️","name":{"ha":"Bulo mai ƙarfi","en":"Strong blocks"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🏖️","kind":"resource","name":{"ha":"Yashi","en":"Sand"},"why":{"ha":"Yana fitowa daga ƙasa. Abu na asali ne.","en":"It comes from the ground. It is a resource."}},{"emoji":"🧱","kind":"product","name":{"ha":"Bulo","en":"Block"},"why":{"ha":"An yi shi daga yashi, siminti da ruwa. Sabon abu ne.","en":"It is made from sand, cement and water. It is a new product."}},{"emoji":"💧","kind":"resource","name":{"ha":"Ruwa","en":"Water"},"why":{"ha":"Ruwa yana fitowa daga yanayi. Abu na asali ne.","en":"Water comes from nature. It is a resource."}},{"emoji":"🧩","kind":"product","name":{"ha":"Bulon interlock","en":"Interlock block"},"why":{"ha":"Sabon abu ne da ake matsewa a injin.","en":"A new product pressed in a machine."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"👀","kind":"safe","name":{"ha":"Tsaya a nesa ka kalli yadda ake yin bulo","en":"Standing back to watch blocks being made"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"✏️","kind":"safe","name":{"ha":"Zana tsarin bangon makaranta","en":"Drawing a plan of a school wall"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🧤","kind":"adult","name":{"ha":"Taɓa siminti da hannu ba tare da safar hannu ba","en":"Touching cement with bare hands"},"why":{"ha":"Siminti yana ƙona fata. Babba ne kawai da safar hannu.","en":"Cement burns skin. Only an adult with gloves."}},{"emoji":"🏋️","kind":"adult","name":{"ha":"Ɗaga bulo masu nauyi","en":"Lifting heavy blocks"},"why":{"ha":"Suna da nauyi. Babba ne kawai.","en":"They are heavy. Only an adult."}},{"emoji":"⚙️","kind":"adult","name":{"ha":"Amfani da injin matsewa","en":"Working the block press"},"why":{"ha":"Zai iya matse yatsa. Babba ne kawai.","en":"It can crush fingers. Only an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa ake sa safar hannu idan ana taɓa siminti?","en":"Why do we wear gloves with cement?"}$j$::jsonb, $j$[{"ha":"Siminti yana ƙona fata","en":"Cement burns skin"},{"ha":"Don ya yi kyau","en":"To look nice"},{"ha":"Don ya yi sanyi","en":"To stay cool"}]$j$::jsonb, 0, $j${"ha":"Siminti yana ƙona fata da idanu, don haka sai da kariya.","en":"Cement burns skin and eyes, so we need protection."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wane abu ne yake manne yashi ya sa bulo ya taurare?","en":"Which material glues the sand and makes the block hard?"}$j$::jsonb, $j$[{"ha":"Siminti","en":"Cement"},{"ha":"Ruwan sama kaɗai","en":"Rain alone"},{"ha":"Ƙura","en":"Dust"}]$j$::jsonb, 0, $j${"ha":"Siminti yana taurare idan ya haɗu da ruwa.","en":"Cement hardens when it meets water."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Menene warkewa (curing)?","en":"What is curing?"}$j$::jsonb, $j$[{"ha":"A bar bulo a inuwa a fesa masa ruwa kwanaki","en":"Keeping blocks in shade and sprinkling water for days"},{"ha":"A ƙona bulo","en":"Burning the blocks"},{"ha":"A jefar da bulo","en":"Throwing blocks away"}]$j$::jsonb, 0, $j${"ha":"Warkewa yana hana bulo tsagewa, ya taurare sosai.","en":"Curing stops cracks so the block hardens fully."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wa ke amfani da injin matsewa?","en":"Who works the block press?"}$j$::jsonb, $j$[{"ha":"Babba mai horo","en":"A trained adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Injin yana iya matse yatsa. Babba ne kawai.","en":"The press can crush fingers. Only a trained adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Menene na musamman game da bulon interlock?","en":"What is special about interlock blocks?"}$j$::jsonb, $j$[{"ha":"Sassansu suna shiga juna","en":"Their parts slot together"},{"ha":"Ba su da nauyi","en":"They weigh nothing"},{"ha":"Ana sha su","en":"You drink them"}]$j$::jsonb, 0, $j${"ha":"Suna shiga juna kamar wasan haɗa hotuna, don haka ana buƙatar ɗan siminti kaɗan.","en":"They slot together like a puzzle, so less mortar is needed."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me yashi yake yi a bulo?","en":"What does sand do in a block?"}$j$::jsonb, $j$[{"ha":"Yana cika shi ya ba shi ƙarfi","en":"Fills it and gives strength"},{"ha":"Yana ƙone shi","en":"Burns it"},{"ha":"Yana sa shi haske","en":"Makes it glow"}]$j$::jsonb, 0, $j${"ha":"Ba tare da yashi ba bulo zai tsage.","en":"Without sand the block would crack."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"👩🏾‍🌾","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Wata manomiya tana son ta fara kiwon kaji da kifi don samun kwai, nama da kifi.","en":"A woman farmer wants to start keeping chickens and fish for eggs, meat and fish."}},{"text":{"ha":"Za ka iya taimaka mata ka koyi yadda ake kula da su?","en":"Can you help her learn how to look after them?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Kaza, kifi, abinci da ruwa abubuwa na asali ne.","en":"Chickens, fish, feed and water are resources."}},{"text":{"ha":"Idan an kula da su da kyau, sai a samu kwai, nama da kifi da ake sayarwa: sabbin abubuwa masu ƙima.","en":"When they are looked after well we get eggs, meat and fish to sell: valuable new products."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Ka wanke hannu da sabulu bayan ka taɓa kaji ko kifi. Kada ka kusanci kaza mara lafiya ko matacciya: ka gaya wa babba.","en":"Wash your hands with soap after touching birds or fish. Never go near a sick or dead bird: tell an adult."}},{"text":{"ha":"Manya ko likitan dabbobi ne ke yin rigakafi da magani. Kada a ci kaza mara lafiya ko wadda ta mutu da kanta. Wannan wasa ne kawai.","en":"Adults or a vet give vaccines and medicine. Never eat a sick bird or one that died by itself. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🐥","title":{"ha":"Kajin gida","en":"Chicks"},"lines":[{"k":"whatIs","text":{"ha":"Ƙananan kaji.","en":"Young chickens."}},{"k":"whatDoes","text":{"ha":"Suna girma su ba da kwai ko nama.","en":"They grow to give eggs or meat."}},{"k":"whyNeeded","text":{"ha":"Suna buƙatar ɗumi, abinci da ruwa mai tsabta.","en":"They need warmth, feed and clean water."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🏠","title":{"ha":"Gidan kaji","en":"Chicken house"},"lines":[{"k":"whatIs","text":{"ha":"Wurin da kaji ke zama.","en":"The place where chickens live."}},{"k":"whatDoes","text":{"ha":"Yana kare su daga ruwan sama, zafi da dabbobi masu cutarwa.","en":"It protects them from rain, heat and harmful animals."}},{"k":"whyNeeded","text":{"ha":"Gida mai tsabta, busasshe da iska mai kyau yana rage cututtuka.","en":"A clean, dry, airy house means less sickness."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🌾","title":{"ha":"Abinci da ruwa","en":"Feed and water"},"lines":[{"k":"whatIs","text":{"ha":"Abincin kaji da ruwa mai tsabta.","en":"Chicken feed and clean water."}},{"k":"whatDoes","text":{"ha":"Suna ba da ƙarfi da girma.","en":"They give strength and growth."}},{"k":"whyNeeded","text":{"ha":"Abinci mai kyau yana ba da kwai da nama mai yawa.","en":"Good feed gives more eggs and meat."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🐟","title":{"ha":"Tafkin kifi","en":"Fish pond"},"lines":[{"k":"whatIs","text":{"ha":"Wurin ruwa da kifi ke rayuwa a ciki.","en":"A water place where fish live."}},{"k":"whatDoes","text":{"ha":"Yana ba kifi wurin girma.","en":"It gives fish room to grow."}},{"k":"whyNeeded","text":{"ha":"Ruwa mai tsabta yana kiyaye lafiyar kifi; ruwa mai ƙazanta yana kashe su.","en":"Clean water keeps fish healthy; dirty water kills them."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"💉","title":{"ha":"Likitan dabbobi da rigakafi","en":"Vet and vaccines"},"lines":[{"k":"whatIs","text":{"ha":"Mutum mai ilimin lafiyar dabbobi.","en":"A person trained in animal health."}},{"k":"whatDoes","text":{"ha":"Yana yin rigakafi yana duba marasa lafiya.","en":"He or she gives vaccines and checks sick animals."}},{"k":"whyNeeded","text":{"ha":"Rigakafi yana hana cututtuka yaɗuwa.","en":"Vaccines stop sickness from spreading."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Kwai, kaza da kifi ana sayar da su. Kulawa mai kyau tana kawo riba.","en":"Eggs, chicken and fish can be sold. Good care brings profit."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
