  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🐔","kind":"resource","name":{"ha":"Kaza","en":"A chicken"},"why":{"ha":"Dabba ce da ake kiwo. Abu na asali ne.","en":"A farm animal. It is a resource."}},{"emoji":"🥚","kind":"product","name":{"ha":"Kwai","en":"Eggs"},"why":{"ha":"Kaza ce ke ba da kwai. Sabon abu ne mai ƙima.","en":"The hen gives eggs. A valuable product."}},{"emoji":"🌾","kind":"resource","name":{"ha":"Abincin kaji","en":"Chicken feed"},"why":{"ha":"Abin da kaji ke ci. Abu na asali ne.","en":"What chickens eat. A resource."}},{"emoji":"🐟","kind":"product","name":{"ha":"Kifi busasshe da aka ƙunsa","en":"Dried, packed fish"},"why":{"ha":"An sarrafa kifi aka ƙunsa. Sabon abu ne.","en":"The fish was processed and packed. A new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🧼","kind":"safe","name":{"ha":"Wanke hannu bayan taɓa kaji","en":"Washing hands after touching chickens"},"why":{"ha":"Wannan lafiya ne kuma yana kare mu.","en":"This is safe and protects us."}},{"emoji":"🌾","kind":"safe","name":{"ha":"Ba kaji abinci tare da babba","en":"Giving chickens feed with an adult"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🤒","kind":"adult","name":{"ha":"Taɓa kaza mara lafiya ko matacciya","en":"Touching a sick or dead bird"},"why":{"ha":"Tana iya yaɗa cuta. Ka gaya wa babba.","en":"It can spread sickness. Tell an adult."}},{"emoji":"💉","kind":"adult","name":{"ha":"Yin allurar rigakafi","en":"Giving a vaccine injection"},"why":{"ha":"Likitan dabbobi ko babba mai horo ne kawai.","en":"Only a vet or trained adult."}},{"emoji":"🍗","kind":"adult","name":{"ha":"Cin kazar da ta mutu da kanta","en":"Eating a bird that died by itself"},"why":{"ha":"Kada ka ci. Ka gaya wa babba.","en":"Never eat it. Tell an adult."}}]}$j$::jsonb);
