  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa muke wanke hannu bayan taɓa kaji?","en":"Why do we wash hands after touching chickens?"}$j$::jsonb, $j$[{"ha":"Kaji na iya ɗauke da ƙwayoyin cuta","en":"Chickens can carry germs"},{"ha":"Don hannu su yi ƙamshi","en":"To make hands smell nice"},{"ha":"Babu dalili","en":"No reason"}]$j$::jsonb, 0, $j${"ha":"Sabulu yana cire ƙwayoyin cuta daga hannu.","en":"Soap removes germs from our hands."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Menene kajin gida ƙanana suka fi buƙata?","en":"What do small chicks need most?"}$j$::jsonb, $j$[{"ha":"Ɗumi, ruwa da abinci","en":"Warmth, water and feed"},{"ha":"Ruwan sama","en":"Rain"},{"ha":"Sanyi","en":"Cold"}]$j$::jsonb, 0, $j${"ha":"Kaji ƙanana ba su iya dumama kansu, suna buƙatar ɗumi, ruwa da abinci.","en":"Chicks cannot keep warm alone: they need warmth, water and feed."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya sa shimfiɗar gidan kaji take bushewa?","en":"Why must the bedding in the chicken house be dry?"}$j$::jsonb, $j$[{"ha":"Danshi yana kawo cututtuka","en":"Damp brings sickness"},{"ha":"Don ya yi laushi kawai","en":"Only to be soft"},{"ha":"Don ya ɗauki ƙura","en":"To collect dust"}]$j$::jsonb, 0, $j${"ha":"Busasshiyar shimfiɗa tana rage cututtuka.","en":"Dry bedding means less sickness."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me zai faru idan aka ba kifi abinci da yawa?","en":"What happens if fish get too much feed?"}$j$::jsonb, $j$[{"ha":"Ragowar abinci yana ƙazanta ruwa","en":"Leftover feed dirties the water"},{"ha":"Kifi su zama masu haske","en":"Fish glow"},{"ha":"Babu komai","en":"Nothing"}]$j$::jsonb, 0, $j${"ha":"Abinci kaɗan-kaɗan yana kiyaye ruwa mai tsabta.","en":"A little feed at a time keeps the water clean."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wa ke yin allurar rigakafi?","en":"Who gives vaccine injections?"}$j$::jsonb, $j$[{"ha":"Likitan dabbobi ko babba mai horo","en":"A vet or trained adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Allura tana buƙatar ilimi da tsabta. Manya masu horo ne kawai.","en":"Injections need training and cleanliness. Only trained adults."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me za ka yi idan ka ga kaza mara lafiya?","en":"What do you do if you see a sick bird?"}$j$::jsonb, $j$[{"ha":"Na gaya wa babba","en":"Tell an adult"},{"ha":"Na ɗauke ta da hannu","en":"Pick it up"},{"ha":"Na ci ta","en":"Eat it"}]$j$::jsonb, 0, $j${"ha":"Kaza mara lafiya tana iya yaɗa cuta. Ka bar ta ka gaya wa babba.","en":"A sick bird can spread sickness. Leave it and tell an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
