  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"👩🏾‍🍳","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A kasuwa, lemo da abarba suna lalacewa da sauri. Wata mata tana son yin lemo ta sayar.","en":"At the market oranges and pineapples spoil fast. A woman wants to make drinks to sell."}},{"text":{"ha":"Za ka iya koyon yadda ake yi cikin tsabta?","en":"Can you learn how to do it cleanly?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Lemo, abarba, zobo, aya da ruwa abubuwa ne na asali.","en":"Oranges, pineapples, zobo, tigernuts and water are resources."}},{"text":{"ha":"Idan an wanke, an sarrafa, an tace aka saka a kwalba mai tsabta, sai a samu lemo da za a sayar.","en":"When washed, processed, strained and bottled cleanly they become drinks to sell."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Tsabta ita ce abu mafi muhimmanci: a wanke hannu, ’ya’yan itace da kwalba. Ruwan zafi, wuƙa da blender na manya ne kawai.","en":"Cleanliness comes first: wash hands, fruit and bottles. Hot water, knives and blenders are for adults only."}},{"text":{"ha":"Kada a sha lemo mai wari ko kumfa: a zubar. A ajiye shi a sanyi. Wannan wasa ne kawai.","en":"Never drink juice that smells sour or foams: throw it away. Keep drinks cold. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🍊","title":{"ha":"’Ya’yan itace","en":"Fruit"},"lines":[{"k":"whatIs","text":{"ha":"Lemo, abarba, kankana ko zobo.","en":"Oranges, pineapple, watermelon or zobo."}},{"k":"whatDoes","text":{"ha":"Suna ba da ɗanɗano, ruwa da bitamin.","en":"They give taste, water and vitamins."}},{"k":"whyNeeded","text":{"ha":"Suna lalacewa da sauri. Sarrafawa yana adana su.","en":"They spoil quickly. Processing saves them."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"💧","title":{"ha":"Ruwa mai tsabta","en":"Clean water"},"lines":[{"k":"whatIs","text":{"ha":"Ruwa mai tsabta, wanda aka tafasa idan ana buƙata.","en":"Clean water, boiled when needed."}},{"k":"whatDoes","text":{"ha":"Yana wanke ’ya’yan itace yana haɗa lemo.","en":"It washes the fruit and makes the drink."}},{"k":"whyNeeded","text":{"ha":"Ruwa maras tsabta yana kawo cututtuka.","en":"Dirty water brings sickness."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🍯","title":{"ha":"Ɗanɗano","en":"Sweetness and flavour"},"lines":[{"k":"whatIs","text":{"ha":"Sukari, zuma, dabino ko ɗan kayan ƙamshi.","en":"Sugar, honey, dates or a little spice."}},{"k":"whatDoes","text":{"ha":"Yana ƙara daɗi.","en":"It adds taste."}},{"k":"whyNeeded","text":{"ha":"Amma kada a saka da yawa, domin lafiya.","en":"But not too much, for health."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🍾","title":{"ha":"Kwalba mai tsabta","en":"Clean bottle"},"lines":[{"k":"whatIs","text":{"ha":"Kwalba mai murfi da aka wanke.","en":"A washed bottle with a lid."}},{"k":"whatDoes","text":{"ha":"Tana adana lemo tana kare shi daga ƙura.","en":"It keeps the drink and protects it from dust."}},{"k":"whyNeeded","text":{"ha":"Kwalba maras tsabta tana lalata lemo.","en":"A dirty bottle spoils the drink."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🧊","title":{"ha":"Sanyi","en":"Keeping it cold"},"lines":[{"k":"whatIs","text":{"ha":"Firji ko kankara.","en":"A fridge or ice."}},{"k":"whatDoes","text":{"ha":"Yana rage lalacewa.","en":"It slows spoiling."}},{"k":"whyNeeded","text":{"ha":"Lemo a rana yana lalacewa da sauri.","en":"Juice in the sun spoils fast."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Lemo da aka yi cikin tsabta ana sayar da shi fiye da ’ya’yan itace danye.","en":"Clean juice sells for more than raw fruit."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
