  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa tsabta take da muhimmanci a yin lemo?","en":"Why is cleanliness so important when making drinks?"}$j$::jsonb, $j$[{"ha":"Datti yana kawo cututtuka","en":"Dirt brings sickness"},{"ha":"Don lemo ya yi tsada","en":"To make it expensive"},{"ha":"Babu dalili","en":"No reason"}]$j$::jsonb, 0, $j${"ha":"Hannu, ’ya’yan itace da kwalba maras tsabta suna lalata lemo suna sa mutane rashin lafiya.","en":"Dirty hands, fruit and bottles spoil drinks and make people ill."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wa ke tafasa zobo?","en":"Who boils the zobo?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Ruwan zafi yana ƙonewa. Babba ne kawai.","en":"Hot water burns. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me za ka yi da lemo mai wari ko kumfa?","en":"What do you do with juice that smells sour or foams?"}$j$::jsonb, $j$[{"ha":"A zubar a gaya wa babba","en":"Throw it away and tell an adult"},{"ha":"A sha shi","en":"Drink it"},{"ha":"A sayar da shi","en":"Sell it"}]$j$::jsonb, 0, $j${"ha":"Lemo ya lalace idan yana wari ko kumfa. Kada a sha.","en":"Juice that smells sour or foams has spoiled. Never drink it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me ya sa ake ajiye lemo a sanyi?","en":"Why do we keep drinks cold?"}$j$::jsonb, $j$[{"ha":"Sanyi yana rage lalacewa","en":"Cold slows spoiling"},{"ha":"Don ya yi nauyi","en":"To make it heavy"},{"ha":"Don ya canza launi","en":"To change colour"}]$j$::jsonb, 0, $j${"ha":"A rana lemo yana lalacewa da sauri.","en":"In the sun juice spoils fast."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Menene zobo?","en":"What is zobo?"}$j$::jsonb, $j$[{"ha":"Abin sha daga busasshen furen zobo","en":"A drink from dried zobo flowers"},{"ha":"Wani nau’in bulo","en":"A type of block"},{"ha":"Wani keke","en":"A bicycle"}]$j$::jsonb, 0, $j${"ha":"Ana tafasa busasshen zobo a tace a sha da sanyi.","en":"Dried zobo is boiled, strained and drunk cold."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me ya sa muke tace lemo?","en":"Why do we strain juice?"}$j$::jsonb, $j$[{"ha":"Don ya yi laushi ba tare da ƙuraje ba","en":"To make it smooth without bits"},{"ha":"Don ya ƙara tsami","en":"To make it sour"},{"ha":"Don a rage shi","en":"To make less of it"}]$j$::jsonb, 0, $j${"ha":"Tacewa tana cire ƙuraje da bawo.","en":"Straining removes bits and pulp."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🎨","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A garinmu akwai tsohuwar al’adar ƙera tukwane. Wata mai ƙera tukwane tana son koya wa yara.","en":"In our town there is an old tradition of making pots. A potter wants to teach children."}},{"text":{"ha":"Za ka iya koyo ka taimaka?","en":"Can you learn and help?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Yumɓu da ruwa abubuwa na asali ne daga ƙasa.","en":"Clay and water are resources from the earth."}},{"text":{"ha":"Idan an ƙera an busar an ƙona, sai a samu tukunya: sabon abu mai amfani.","en":"When shaped, dried and fired they become a pot: a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Wuta da murhun ƙona tukwane suna da zafi sosai: manya ne kawai. Kada ka taɓa tukunya da aka ƙona kafin ta huce.","en":"Fire and the kiln are very hot: adults only. Never touch a fired pot before it is cool."}},{"text":{"ha":"Ƙurar yumɓu busasshe tana cutar da huhu: a goge da rigar da aka jiƙa, kada a share busasshe. A wanke hannu. Wannan wasa ne kawai.","en":"Dry clay dust harms the lungs: wipe with a damp cloth, never sweep it dry. Wash your hands. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⛰️","title":{"ha":"Yumɓu","en":"Clay"},"lines":[{"k":"whatIs","text":{"ha":"Ƙasa mai ɗaure da laushi.","en":"Soft, sticky earth."}},{"k":"whatDoes","text":{"ha":"Idan ta jiƙa tana laushi, sai a ƙera ta.","en":"When wet it is soft and can be shaped."}},{"k":"whyNeeded","text":{"ha":"Idan an ƙona ta, tana taurare ta zama tukunya.","en":"When fired it turns hard like stone."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"💧","title":{"ha":"Ruwa","en":"Water"},"lines":[{"k":"whatIs","text":{"ha":"Ruwa mai tsabta.","en":"Clean water."}},{"k":"whatDoes","text":{"ha":"Yana sa yumɓu ya yi laushi.","en":"It makes clay soft."}},{"k":"whyNeeded","text":{"ha":"Ruwa da yawa yana sa shi ruwa-ruwa; kaɗan yana sa shi ya tsage.","en":"Too much makes it sloppy; too little makes it crack."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🤲","title":{"ha":"Hannu da kayan aiki","en":"Hands and tools"},"lines":[{"k":"whatIs","text":{"ha":"Hannu, ƙaramin sanda da zane mai laushi.","en":"Hands, a small stick and a soft cloth."}},{"k":"whatDoes","text":{"ha":"Suna taimakawa wajen ƙera da gogewa.","en":"They help to shape and smooth."}},{"k":"whyNeeded","text":{"ha":"Gogewa yana hana tsagewa.","en":"Smoothing prevents cracks."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🌤️","title":{"ha":"Busarwa a hankali","en":"Slow drying"},"lines":[{"k":"whatIs","text":{"ha":"A bar tukunya ta bushe a inuwa.","en":"Let the pot dry in the shade."}},{"k":"whatDoes","text":{"ha":"Tana fitar da ruwa daga tukunya.","en":"It lets the water leave the pot."}},{"k":"whyNeeded","text":{"ha":"Idan ta bushe da sauri ko ba ta bushe ba, za ta fashe a wuta.","en":"If dried too fast, or not dry, it will crack in the fire."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🔥","title":{"ha":"Ƙonawa","en":"Firing"},"lines":[{"k":"whatIs","text":{"ha":"Ƙona tukunya a wuta mai ƙarfi. Manya ne.","en":"Heating the pot in a strong fire. Adults only."}},{"k":"whatDoes","text":{"ha":"Yana mai da yumɓu abu mai ƙarfi kamar dutse.","en":"It turns clay into something hard like stone."}},{"k":"whyNeeded","text":{"ha":"Ba tare da ƙonawa ba, tukunya za ta narke a ruwa.","en":"Without firing, the pot melts in water."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Ana iya sayar da tukunya ko amfani da ita a gida, har ma don sanyaya abinci.","en":"A pot can be sold or used at home, even to keep food cool."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pdig', 0, $j${"emoji":"⛏️","name":{"ha":"Tono yumɓu","en":"Dig the clay"},"text":{"ha":"Manya suna tono yumɓu mai kyau daga wuri mai tsaro.","en":"Adults dig good clay from a safe place."}}$j$::jsonb);
