  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Yaya muke gano ramin tube?","en":"How do we find the hole in a tube?"}$j$::jsonb, $j$[{"ha":"Da ruwa, kumfa yana nuna ramin","en":"In water: bubbles show the hole"},{"ha":"Da wuta","en":"With fire"},{"ha":"Da ido rufe","en":"With closed eyes"}]$j$::jsonb, 0, $j${"ha":"Iska tana fita ta rami tana yin kumfa a ruwa.","en":"Air escapes through the hole and makes bubbles in water."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wa ke amfani da kayan cire tayar?","en":"Who uses the tyre levers?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Suna iya matse yatsa. Babba ne kawai.","en":"They can pinch fingers. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Menene sarƙa take yi?","en":"What does the chain do?"}$j$::jsonb, $j$[{"ha":"Tana juya ƙafar baya idan an taka feda","en":"It turns the back wheel when you pedal"},{"ha":"Tana tsayar da keke","en":"It stops the bike"},{"ha":"Tana cika iska","en":"It pumps air"}]$j$::jsonb, 0, $j${"ha":"Sarƙa tana ɗaukar ƙarfin feda zuwa ƙafa.","en":"The chain carries the pedal power to the wheel."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Ina ake gwada birki?","en":"Where do we test brakes?"}$j$::jsonb, $j$[{"ha":"A wuri mai lafiya, a hankali","en":"In a safe place, slowly"},{"ha":"A kan babbar hanya","en":"On a main road"},{"ha":"Cikin gida da gudu","en":"Fast, inside the house"}]$j$::jsonb, 0, $j${"ha":"Motoci a hanya suna da haɗari.","en":"Cars on the road are dangerous."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Menene famfo yake yi?","en":"What does the pump do?"}$j$::jsonb, $j$[{"ha":"Yana cika tayar da iska","en":"Fills the tyre with air"},{"ha":"Yana yanke sarƙa","en":"Cuts the chain"},{"ha":"Yana ƙona roba","en":"Burns the rubber"}]$j$::jsonb, 0, $j${"ha":"Tayar da iska take ɗaukar keke.","en":"A tyre full of air carries the bike."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me ya kamata ka sa idan za ka hau keke?","en":"What should you wear when riding?"}$j$::jsonb, $j$[{"ha":"Hular kwano da takalmi","en":"A helmet and shoes"},{"ha":"Babu komai","en":"Nothing"},{"ha":"Safar hannu ta wuta","en":"Fireproof gloves"}]$j$::jsonb, 0, $j${"ha":"Hular kwano tana kare kai.","en":"A helmet protects your head."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🏭","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A garinmu mutane suna sare bishiyoyi don yin gawayi. Sharar itace da kwasfar gyada kuma suna taruwa.","en":"In our town people cut trees for charcoal. Sawdust and groundnut shells pile up."}},{"text":{"ha":"Za ka iya taimaka mana mu yi gawayi daga sharar?","en":"Can you help us make charcoal from this waste?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Sharar itace da kwasfa abubuwa na asali ne: sharar da za a iya amfani da ita.","en":"Sawdust and shells are resources: waste that can be used again."}},{"text":{"ha":"Idan an ƙona a hankali, an niƙa, an haɗa da manne aka matse, sai a samu gawayin girki: sabon abu.","en":"When charred slowly, crushed, mixed with a binder and pressed, they become cooking briquettes: a new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Ƙona abu yana da hayaƙi mai haɗari: manya ne kawai, a waje, nesa da gida. Hayaƙin gawayi (carbon monoxide) yana kashe mutum. Kada a taɓa girki ko ƙona gawayi a cikin ɗaki.","en":"Burning makes dangerous smoke: adults only, outdoors, far from houses. Charcoal fumes (carbon monoxide) can kill. Never cook or burn charcoal inside a room."}},{"text":{"ha":"Ƙurar gawayi da ta itace tana cutar da huhu: a sa abin rufe hanci. Gawayi mai zafi yana ƙonewa: kada ka taɓa. Wannan wasa ne kawai.","en":"Charcoal and wood dust harm the lungs: wear a mask. Hot charcoal burns: never touch it. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🪵","title":{"ha":"Sharar itace da kwasfa","en":"Sawdust and shells"},"lines":[{"k":"whatIs","text":{"ha":"Sharar itace, kwasfar gyada ko ta shinkafa.","en":"Sawdust, groundnut or rice shells."}},{"k":"whatDoes","text":{"ha":"Suna ƙonewa suna ba da zafi.","en":"They burn and give heat."}},{"k":"whyNeeded","text":{"ha":"Ba sai an sare ƙarin bishiyoyi ba.","en":"No more trees need to be cut."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"⚫","title":{"ha":"Gawayi (char)","en":"Char"},"lines":[{"k":"whatIs","text":{"ha":"Itace da aka ƙona a hankali da ƙarancin iska.","en":"Wood burnt slowly with little air."}},{"k":"whatDoes","text":{"ha":"Yana ƙonewa a hankali yana ba da zafi mai yawa da ƙarancin hayaƙi.","en":"It burns slowly with strong heat and little smoke."}},{"k":"whyNeeded","text":{"ha":"Yana sauƙaƙa girki.","en":"It makes cooking easier."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🥣","title":{"ha":"Manne (sitaci)","en":"Binder (starch)"},"lines":[{"k":"whatIs","text":{"ha":"Sitaci da aka dafa da ruwa. Ana samun sa daga rogo!","en":"Starch cooked in water. It comes from cassava!"}},{"k":"whatDoes","text":{"ha":"Yana manna ƙurar gawayi wuri ɗaya.","en":"It sticks the charcoal dust together."}},{"k":"whyNeeded","text":{"ha":"Ba tare da manne ba, ƙwallon gawayi za ta farfashe.","en":"Without a binder the briquette crumbles."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🟤","title":{"ha":"Ƙira ko matsewa","en":"Mould or press"},"lines":[{"k":"whatIs","text":{"ha":"Ƙira ko hannu da ke ba gawayi siffa.","en":"A mould or hands that give the briquette its shape."}},{"k":"whatDoes","text":{"ha":"Yana ba gawayi siffa ɗaya.","en":"It gives every briquette the same shape."}},{"k":"whyNeeded","text":{"ha":"Siffa ɗaya tana ƙonewa daidai.","en":"An even shape burns evenly."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"☀️","title":{"ha":"Busarwa a rana","en":"Drying in the sun"},"lines":[{"k":"whatIs","text":{"ha":"Ana jera gawayi a rana kwanaki.","en":"Briquettes are laid in the sun for days."}},{"k":"whatDoes","text":{"ha":"Tana fitar da ruwa.","en":"It drives out the water."}},{"k":"whyNeeded","text":{"ha":"Gawayi mai ɗanshi yana hayaƙi, bai ƙonewa da kyau.","en":"Damp briquettes smoke and burn badly."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Gawayin da aka yi daga shara yana adana bishiyoyi kuma ana iya sayar da shi.","en":"Briquettes made from waste save trees and can be sold."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ccollect', 0, $j${"emoji":"🧹","name":{"ha":"Tara sharar","en":"Collect the waste"},"text":{"ha":"Ana tara sawdust ko kwasfa mai tsabta.","en":"Collect clean sawdust or shells."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cdry', 1, $j${"emoji":"☀️","name":{"ha":"Busar a rana","en":"Dry it in the sun"},"text":{"ha":"Ana shanya su a rana sai su bushe.","en":"Spread them in the sun until dry."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'csieve', 2, $j${"emoji":"🧺","name":{"ha":"Cire duwatsu da ƙusoshi","en":"Remove stones and nails"},"text":{"ha":"Ana tace duwatsu da ƙusoshi.","en":"Sieve out stones and nails."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'hburn', 3, $j${"emoji":"🔥","name":{"ha":"Ƙona a ganga a waje","en":"Burn in a drum outdoors"},"text":{"ha":"Manya suna ƙona sharar a hankali a ganga, a waje, nesa da gida.","en":"Adults burn the waste slowly in a drum, outdoors and far from houses."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'hair', 4, $j${"emoji":"🚫","name":{"ha":"Rage iska","en":"Limit the air"},"text":{"ha":"Manya suna rufe ganga don ƙarancin iska, kada ta zama toka.","en":"Adults cover the drum so little air gets in and it does not turn to ash."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'hwater', 5, $j${"emoji":"💧","name":{"ha":"Kashe da ruwa ko yashi","en":"Put out with water or sand"},"text":{"ha":"Manya suna kashe wuta da ruwa ko yashi.","en":"Adults put out the fire with water or sand."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'hcool', 6, $j${"emoji":"⏳","name":{"ha":"A bar ya huce","en":"Let it cool"},"text":{"ha":"Manya suna barin gawayin ya huce sarai.","en":"Adults let the char cool completely."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pcrush', 7, $j${"emoji":"⚙️","name":{"ha":"Niƙa gawayin","en":"Crush the char"},"text":{"ha":"Babba yana niƙa gawayi ya zama ƙura, da abin rufe hanci.","en":"An adult crushes the char to powder, wearing a dust mask."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pstarch', 8, $j${"emoji":"🥣","name":{"ha":"Dafa sitaci","en":"Cook the starch"},"text":{"ha":"Babba yana dafa sitaci da ruwa ya zama manne.","en":"An adult cooks starch with water to make glue."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pmix', 9, $j${"emoji":"🥄","name":{"ha":"Haɗa da manne","en":"Mix with the binder"},"text":{"ha":"Ana haɗa ƙurar gawayi da manne, da safar hannu.","en":"Mix the charcoal dust with the binder, wearing gloves."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ppress', 10, $j${"emoji":"🟤","name":{"ha":"Matse a ƙira","en":"Press into shapes"},"text":{"ha":"Ana matsewa a ƙira ko a yi ƙwallo.","en":"Press into moulds or roll into balls."},"kid":true}$j$::jsonb);
