  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'char', 1, $j${"id":"char","emoji":"🔥","name":{"ha":"Ƙona zuwa gawayi (manya)","en":"Charring (adults only)"},"steps":["hburn","hair","hwater","hcool"],"summary":{"ha":"Ƙonawa: manya, a waje, ƙarancin iska, kashewa, huce.","en":"Charring: adults, outdoors, little air, put out, cool down."},"result":{"emoji":"⚫","name":{"ha":"Gawayi (char)","en":"Char"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'press', 2, $j${"id":"press","emoji":"🟤","name":{"ha":"Haɗawa, matsewa da busarwa","en":"Mix, press and dry"},"steps":["pcrush","pstarch","pmix","ppress","psun"],"summary":{"ha":"Haɗa da manne, a matse, a busar a rana.","en":"Mix with binder, press, dry in the sun."},"result":{"emoji":"🔥","name":{"ha":"Gawayin girki","en":"Cooking briquettes"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🪵","kind":"resource","name":{"ha":"Sharar itace","en":"Sawdust"},"why":{"ha":"Sharar da za a iya sake amfani da ita. Abu na asali ne.","en":"Waste that can be used again. A resource."}},{"emoji":"🔥","kind":"product","name":{"ha":"Gawayin ƙwallo","en":"A briquette"},"why":{"ha":"An yi shi daga shara. Sabon abu ne.","en":"It is made from waste. A new product."}},{"emoji":"🥜","kind":"resource","name":{"ha":"Kwasfar gyada","en":"Groundnut shells"},"why":{"ha":"Sharar noma ce. Abu na asali ne.","en":"Farm waste. A resource."}},{"emoji":"📦","kind":"product","name":{"ha":"Gawayi da aka ƙunsa don sayarwa","en":"Packed briquettes for sale"},"why":{"ha":"An sarrafa aka ƙunsa. Sabon abu ne.","en":"Processed and packed. A new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"☀️","kind":"safe","name":{"ha":"Busar da gawayin ƙwallo a rana","en":"Drying briquettes in the sun"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🥄","kind":"safe","name":{"ha":"Haɗa ƙurar gawayi da manne, da safar hannu","en":"Mixing charcoal dust with binder, wearing gloves"},"why":{"ha":"Wannan lafiya ne tare da babba.","en":"This is safe with an adult nearby."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Ƙona sharar a ganga","en":"Burning waste in a drum"},"why":{"ha":"Wuta da hayaƙi. Babba ne kawai, a waje.","en":"Fire and smoke. Only an adult, outdoors."}},{"emoji":"🏠","kind":"adult","name":{"ha":"Girki ko ƙona gawayi a cikin ɗaki","en":"Cooking or burning charcoal inside a room"},"why":{"ha":"Hayaƙin yana kashe mutum. Kada ka taɓa.","en":"The fumes can kill. Never do it."}},{"emoji":"🥵","kind":"adult","name":{"ha":"Taɓa gawayi mai zafi","en":"Touching hot charcoal"},"why":{"ha":"Yana ƙonewa. Jira babba.","en":"It burns. Wait for an adult."}}]}$j$::jsonb);
