  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa ba a girki da gawayi a cikin ɗaki?","en":"Why do we never cook with charcoal inside a room?"}$j$::jsonb, $j$[{"ha":"Hayaƙinsa (carbon monoxide) yana kashe mutum","en":"Its fumes (carbon monoxide) can kill"},{"ha":"Yana ɗaukar sarari","en":"It takes space"},{"ha":"Yana da nauyi","en":"It is heavy"}]$j$::jsonb, 0, $j${"ha":"Carbon monoxide ba shi da ƙamshi amma yana kashewa. Ana girki a waje ko wuri mai iska.","en":"Carbon monoxide has no smell but kills. Cook outdoors or where air flows."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wa ke ƙona sharar zuwa gawayi?","en":"Who burns the waste into char?"}$j$::jsonb, $j$[{"ha":"Manya, a waje","en":"Adults, outdoors"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa a cikin ɗaki","en":"Anyone indoors"}]$j$::jsonb, 0, $j${"ha":"Wuta da hayaƙi suna da haɗari.","en":"Fire and smoke are dangerous."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Menene aikin manne (sitaci)?","en":"What does the binder (starch) do?"}$j$::jsonb, $j$[{"ha":"Yana manna ƙurar gawayi wuri ɗaya","en":"It sticks the charcoal dust together"},{"ha":"Yana ƙara hayaƙi","en":"It adds smoke"},{"ha":"Yana sa gawayi ya narke","en":"It melts the charcoal"}]$j$::jsonb, 0, $j${"ha":"Ba tare da manne ba gawayin ƙwallo zai farfashe.","en":"Without a binder the briquette would crumble."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me ya sa ake busar da gawayin ƙwallo a rana?","en":"Why dry briquettes in the sun?"}$j$::jsonb, $j$[{"ha":"Ruwa a ciki yana sa hayaƙi","en":"Water inside makes smoke"},{"ha":"Don su yi sanyi","en":"To make them cold"},{"ha":"Don su canza launi","en":"To change colour"}]$j$::jsonb, 0, $j${"ha":"Gawayi busasshe yana ƙonewa da kyau.","en":"Dry briquettes burn well."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Ta yaya wannan gawayi yake taimakon muhalli?","en":"How do these briquettes help nature?"}$j$::jsonb, $j$[{"ha":"Ba sai an sare ƙarin bishiyoyi ba","en":"Fewer trees need to be cut"},{"ha":"Suna ƙara hayaƙi","en":"They add smoke"},{"ha":"Suna lalata ƙasa","en":"They spoil the soil"}]$j$::jsonb, 0, $j${"ha":"Ana amfani da shara maimakon bishiyoyi.","en":"We use waste instead of trees."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Menene “char”?","en":"What is “char”?"}$j$::jsonb, $j$[{"ha":"Itace da aka ƙona a hankali da ƙarancin iska","en":"Wood burnt slowly with little air"},{"ha":"Toka","en":"Ash"},{"ha":"Ruwa","en":"Water"}]$j$::jsonb, 0, $j${"ha":"Char yana ƙonewa a hankali yana ba da zafi mai yawa.","en":"Char burns slowly with strong heat."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
