  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🎨","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Rigar wani yaro ta yage a hannu, maɓallinta kuma ya faɗi. Tela zai koya mana yadda ake gyara.","en":"A boy’s shirt has a torn sleeve and a lost button. A tailor will teach us how to fix it."}},{"text":{"ha":"Za ka iya koyo ka taimaka?","en":"Can you learn and help?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Yadi, zare da allura abubuwa na asali ne.","en":"Cloth, thread and needles are resources."}},{"text":{"ha":"Idan an auna, an yanka an ɗinka, sai a samu riga ko jaka: sabon abu mai amfani.","en":"When measured, cut and sewn they become a shirt or a bag: a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Allura, fil da almakashi suna da kaifi. Yara su yi amfani da allura mara kaifi da kulawar babba. Almakashi da wuƙa na manya ne.","en":"Needles, pins and scissors are sharp. Children use a blunt needle with an adult nearby. Scissors and knives are for adults."}},{"text":{"ha":"Injin ɗinki da maƙo (iron) na manya ne kawai. Kada ka saka yatsa kusa da allurar injin. Wannan wasa ne kawai.","en":"Sewing machines and irons are for adults only. Never put fingers near the machine needle. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"📏","title":{"ha":"Zaren auna","en":"Tape measure"},"lines":[{"k":"whatIs","text":{"ha":"Zare mai lambobi don auna.","en":"A tape with numbers for measuring."}},{"k":"whatDoes","text":{"ha":"Yana auna ƙirji, kugu da tsayi.","en":"It measures chest, waist and length."}},{"k":"whyNeeded","text":{"ha":"Auna daidai yana sa tufa ta yi daidai.","en":"Exact measuring makes clothes fit."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🧵","title":{"ha":"Yadi","en":"Cloth"},"lines":[{"k":"whatIs","text":{"ha":"Kayan da ake ɗinka tufafi daga ciki.","en":"The material clothes are sewn from."}},{"k":"whatDoes","text":{"ha":"Yana zama riga, wando ko jaka.","en":"It becomes a shirt, trousers or a bag."}},{"k":"whyNeeded","text":{"ha":"Yadi mai kyau yana sa tufa ta daɗe.","en":"Good cloth makes a garment last."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🪡","title":{"ha":"Zare da allura","en":"Thread and needle"},"lines":[{"k":"whatIs","text":{"ha":"Zare mai ƙarfi da allura.","en":"Strong thread and a needle."}},{"k":"whatDoes","text":{"ha":"Suna haɗa guntun yadi.","en":"They join pieces of cloth."}},{"k":"whyNeeded","text":{"ha":"Zare mai ƙarfi yana hana yagewa.","en":"Strong thread stops tearing."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"✂️","title":{"ha":"Alli da almakashi","en":"Chalk and scissors"},"lines":[{"k":"whatIs","text":{"ha":"Alli yana yin alama, almakashi yana yankawa.","en":"Chalk marks, scissors cut."}},{"k":"whatDoes","text":{"ha":"Alama tana nuna inda za a yanka.","en":"The mark shows where to cut."}},{"k":"whyNeeded","text":{"ha":"Yankan daidai yana hana ɓarnar yadi.","en":"Exact cutting saves cloth."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🧰","title":{"ha":"Injin ɗinki","en":"Sewing machine"},"lines":[{"k":"whatIs","text":{"ha":"Na’ura mai ɗinka da sauri.","en":"A machine that sews quickly."}},{"k":"whatDoes","text":{"ha":"Tana ɗinka dogon ɗinki mai ƙarfi.","en":"It sews long, strong seams."}},{"k":"whyNeeded","text":{"ha":"Tana rage lokaci, amma manya ne kawai ke amfani da ita.","en":"It saves time, but only adults use it."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Tela yana samun kuɗi daga dinki da gyara, kuma yana ba mutane tufafi masu kyau.","en":"A tailor earns from sewing and mending and gives people well-fitting clothes."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
