  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me ya sa ake yin alama da alli kafin a yanka?","en":"Why mark with chalk before cutting?"}$j$::jsonb, $j$[{"ha":"Don a yanka daidai","en":"So we cut in the right place"},{"ha":"Don yadi ya yi kyau","en":"To decorate the cloth"},{"ha":"Don a yi wasa","en":"For fun"}]$j$::jsonb, 0, $j${"ha":"Alama tana nuna inda za a yanka, kuma tana hana ɓarnar yadi.","en":"The mark shows where to cut and saves cloth."}$j$::jsonb, 5);
